def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    # Initialize the output message
    message = []

    # Add the DISCARD message
    message.append(b'\x02' + b'DISCARD')

    # Add the number of records to discard
    if n != -1:
        message.append(b'\x01' + b'n' + str(n).encode('ascii'))

    # Add the query ID to discard for
    if qid != -1:
        message.append(b'\x01' + b'qid' + str(qid).encode('ascii'))

    # Add the dehydration hooks
    if dehydration_hooks is not None:
        for type_, hook in dehydration_hooks.items():
            message.append(b'\x01' + b'dehydration_hook' + str(hook).encode('ascii'))

    # Add the hydration hooks
    if hydration_hooks is not None:
        for type_, hook in hydration_hooks.items():
            message.append(b'\x01' + b'hydration_hook' + str(hook).encode('ascii'))

    # Add the handler functions
    if handlers is not None:
        for key, value in handlers.items():
            message.append(b'\x01' + key.encode('ascii') + b'\x02' + str(value).encode('ascii'))

    # Encode and return the message
    return b'\x01' + b'\x05'.join(message)
