def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    app_manifest = app.spec.manifest
    resource_definitions = app_manifest.resource_definitions
    for resource_definition in resource_definitions:
        resource_name = resource_definition.name
        resource_plural = resource_definition.name.lower() + 's'
        resource_definition = {
            'plural': resource_plural,
            'schema': {
                'properties': {}
            }
        }
        property_definitions = resource_definition.property_definitions
        for property_definition in property_definitions:
            property_name = property_definition.name
            property_type = property_definition.type
            property_definition = {
                'type': property_type,
                'default': property_type == 'string' ? '' : None
            }
            resource_definition['properties'][property_name] = property_definition
        resource_definitions[resource_name] = resource_definition
    app_manifest.resource_definitions = resource_definitions
    return app_manifest
