def parse_subparser_arguments(unparsed_arguments, subparsers):
    # Create an empty dictionary to store parsed arguments for each subparser
    parsed_args = {}
    # Create a list to store remaining arguments that could not be parsed
    remaining_args = []

    # Loop through each argument in the sequence of unparsed_arguments
    for arg in unparsed_arguments:
        # Loop through each subparser in the subparsers dictionary
        for subparser_name, subparser in subparsers.items():
            # Try parsing the current argument with the current subparser
            try:
                # Parse the argument with the current subparser
                parsed_args[subparser_name] = subparser.parse_args([arg])

                # Break out of the subparser loop, as the current argument has been parsed
                break
            except BaseException:
                # If the argument could not be parsed, continue to the next subparser
                continue
        else:
            # If none of the subparsers recognized the current argument, add it to the remaining arguments
            remaining_args.append(arg)

    # Return the parsed arguments and remaining arguments
    return parsed_args, remaining_args

