def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes

    This method takes in a string representing a human readable file size (e.g. 500K), and
    converts it to an integer representation (in bytes). The resulting value is an approximation
    as the input value is often rounded.

    Args:
        size: A string representing a human readable file size

    Returns:
        A decimal representation of the file size in bytes
    """
    suffixes = ["", "K", "M", "G", "T", "P", "E", "Z", "Y"]
    for suffix in suffixes:
        if size.endswith(suffix):
            size = float(size[:-1])
            if suffix == "":
                size *= 1
            elif suffix == "K":
                size *= 1000
            elif suffix == "M":
                size *= 1000000
            elif suffix == "G":
                size *= 1000000000
            elif suffix == "T":
                size *= 1000000000000
            elif suffix == "P":
                size *= 1000000000000000
            elif suffix == "E":
                size *= 1000000000000000000
            elif suffix == "Z":
                size *= 1000000000000000000000
            elif suffix == "Y":
                size *= 1000000000000000000000000
            break
    return int(size)
