def resolve_config_env(config, overrides=None):
    env = get_env()
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('$'):
            key_parts = key.split('.')
            key_env = '.'.join(key_parts[1:])
            value = env.get(key_env, value)
