    make_value = lambda bin_: bin_.content

# Set default value for field_names if not provided
if field_names is None:
    field_names = ("x", "y")

# Create a new graph with the same number of dimensions as field_names
graph = Graph(len(field_names))

# Iterate over each bin in the histogram
for bin_ in hist.bins:
    # Get the values for the point from the make_value function
    values = make_value(bin_)

    # Get the coordinates of the point
    if get_coordinate == "left":
        coordinates = (bin_.start, values)
    elif get_coordinate == "right":
        coordinates = (bin_.end, values)
    elif get_coordinate == "middle":
        coordinates = (bin_.start + (bin_.end - bin_.start) / 2, values)
    else:
        raise ValueError("Invalid get_coordinate argument: {}".format(get_coordinate))

    # Add the point to the graph
    graph.add_point(*coordinates)

# Set the scale of the graph
if scale is None:
    graph.scale = hist.scale
elif scale is True:
    graph.scale = hist.scale
else:
    graph.scale = scale

